const item = $input.item.json;
const q = item.query || {};
const ok = v => typeof v === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(v);
return { json: { review: ok(q.review) ? q.review : '', token: ok(q.token) ? q.token : '', config: item.config } };

